// Extract incoming lead payload and assign correlation ID
const incoming = $input.first().json;
const body = incoming.body || incoming;
const correlationId = body.correlationId || incoming.headers?.['x-correlation-id'] || `corr_n8n_lead_${Date.now()}`;

const rawSegment = (body.segment || body.campaign_segment || '').toUpperCase();
const country = body.country || body.location || 'International';
const name = body.name || body.contact_name || 'Private Sovereign Investor';
const email = body.email || 'privateadvisory@emanuelrendas.com';
const phone = body.phone || body.whatsapp || '+971501234567';
const budgetAed = Number(body.budgetAed || body.budget_aed || body.budget || 15000000);
const notes = body.notes || body.mandate || 'Autonomous acquisition inquiry';

// Determine segment if missing
let segment = rawSegment;
if (!['PT_HNW', 'ES_HNW', 'UK_NONDOM', 'DLD_BUYER', 'DLD_SELLER'].includes(segment)) {
  if (country.toLowerCase().includes('portugal') || notes.toLowerCase().includes('nhr')) segment = 'PT_HNW';
  else if (country.toLowerCase().includes('spain') || notes.toLowerCase().includes('beckham')) segment = 'ES_HNW';
  else if (country.toLowerCase().includes('uk') || country.toLowerCase().includes('united kingdom') || notes.toLowerCase().includes('non-dom')) segment = 'UK_NONDOM';
  else if (notes.toLowerCase().includes('sell') || notes.toLowerCase().includes('secondary')) segment = 'DLD_SELLER';
  else segment = 'DLD_BUYER';
}

return [{
  json: {
    correlationId,
    lead: {
      name,
      email,
      phone,
      country,
      segment,
      budgetAed,
      notes
    },
    timestamp: new Date().toISOString()
  }
}];

